const WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** UPU S10 check digit for an 8-digit serial number (see docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  if (!/^\d{8}$/.test(serial)) throw new Error('S10 serial must be 8 digits');
  const sum = WEIGHTS.reduce((acc, weight, i) => acc + weight * Number(serial[i]), 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

/** True for `XX#########AT` with a correct check digit (input must be upper case). */
export function isValidAtpTrackingNumber(value: string): boolean {
  const match = /^[A-Z]{2}(\d{8})(\d)AT$/.exec(value);
  return match !== null && s10CheckDigit(match[1]) === Number(match[2]);
}
